fn clampv(v: i32) -> i32 {
    if v > 9 { return 9; }
    if v < -9 { return -9; }
    v
}

fn fieldx(y: i32, cy: i32) -> i32 {
    clampv((cy - y) / 14 + 2)
}

fn fieldy(x: i32, cx: i32) -> i32 {
    clampv((x - cx) / 14)
}

fn frame(t: i32) {
    let tab = [0, 25, 49, 71, 90, 106, 117, 124, 127, 124, 117, 106, 90, 71, 49, 25, 0, -25, -49, -71, -90, -106, -117, -124, -127, -124, -117, -106, -90, -71, -49, -25];
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let cx: i32 = w / 2 + tab[(t / 7) & 31] * 80 / 127;
    let cy: i32 = h / 2 + tab[((t / 9) + 8) & 31] * 60 / 127;
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        let mut i: i32 = 0;
        while i < 5 {
            host::display::state_set(8 + i * 2, (60 + i * 80) * 8);
            host::display::state_set(9 + i * 2, (90 + i * 50) * 8);
            i = i + 1;
        }
    }
    host::display::clear(0x0a0c10);
    let mut gy: i32 = 0;
    while gy < 8 {
        let mut gx: i32 = 0;
        while gx < 8 {
            let px: i32 = 28 + gx * 56;
            let py: i32 = 28 + gy * 56;
            let vx: i32 = fieldx(py, cy);
            let vy: i32 = fieldy(px, cx);
            host::display::draw_line(px, py, px + vx * 2, py + vy * 2, 0x30485a);
            host::display::fill_rect(px + vx * 2 - 1, py + vy * 2 - 1, 2, 2, 0x5a7890);
            gx = gx + 1;
        }
        gy = gy + 1;
    }
    let mut i: i32 = 0;
    while i < 5 {
        let mut x: i32 = host::display::state_get(8 + i * 2);
        let mut y: i32 = host::display::state_get(9 + i * 2);
        x = x + fieldx(y / 8, cy) * 3;
        y = y + fieldy(x / 8, cx) * 3;
        if x < 0 { x = x + w * 8; }
        if x >= w * 8 { x = x - w * 8; }
        if y < 0 { y = y + h * 8; }
        if y >= h * 8 { y = y - h * 8; }
        host::display::state_set(8 + i * 2, x);
        host::display::state_set(9 + i * 2, y);
        host::display::fill_rect(x / 8 - 3, y / 8 - 3, 6, 6, 0xf0f0f0);
        i = i + 1;
    }
    host::display::draw_string(8, h - 20, "WANDERING VORTEX", 0x506070, 1);
    host::display::present();
}
